// `teardown.ps1`: the elevated half of `arashouse teardown` (ticket 49), generated by the CLI from the same
// constants as the guards (names.ts, guards.ts, flavors.ts) and run by the captain, once, when the whole
// pool is to go. The WSL half has destroyed every slot through the broker first; this script removes what
// only an administrator can: the goldens (`-Goldens`), the SQL objects (`setup-sql.ps1 -Uninstall`, ticket
// 22; `-KeepSql` skips), the broker service (`setup-host.ps1 -Uninstall`, ticket 21) and, with
// `-RemoveRoot`, the install root. Before and after, it fingerprints the deny-list (ps-common.ts) and
// lists what of the tool is left, by the allowlist's names only. Pure: this module only builds text.
// docs/teardown.md describes the script; its tests are teardown-script.test.ts (the text) and
// test/teardown.test.ts (the script under Windows PowerShell, when there is one).

import { FLAVOR_KEYS, type FlavorKey } from "../core/flavors.js";
import { DENIED_INSTALL_ROOTS, DENIED_SERVICE_PREFIXES, assertValidRoot } from "../core/guards.js";
import {
  BROKER_SERVICE_NAME,
  BUILD_SCRATCH_SUFFIXES,
  DEFAULT_INSTALL_ROOT,
  UTILITY_DATABASE,
  agentServiceName,
  buildNames,
  buildScratch,
  databaseName,
  goldenDir,
  webAlias,
} from "../core/names.js";
import { ROOT_FOLDERS, psQuote } from "../core/setup-host.js";
import { POOL_LOGIN, SIGNERS, SQL_DATA_SOURCE } from "../core/setup-sql.js";
import { PS_DENY_LIST_PRINTS, PS_IIS, PS_PATHS_AND_PRINTS } from "./ps-common.js";

/** The two scripts the teardown bundle runs, relative to `teardown.ps1`'s folder. */
export const TEARDOWN_CHILDREN = { host: "host\\setup-host.ps1", sql: "sql\\setup-sql.ps1" } as const;

/**
 * The inbound rule ticket 44's `scripts/host-tuning.ps1 -FirewallWslOnly` added; no version since ticket 55 adds it, and
 * `host-tuning.ps1 -Undo Firewall` removes it.
 */
export const HOST_TUNING_FIREWALL_RULE = "arashouse-http-in-wsl";

/** Where `scripts/host-tuning.ps1` records what ticket 44's version applied, under the user's `%LOCALAPPDATA%`. */
export const HOST_TUNING_STATE = "arashouse\\host-tuning\\state.json";

/** The file the script writes its result to (with `-Apply`), next to itself: the root may be gone by then. */
export const TEARDOWN_RESULT_FILE = "teardown-result.json";

export interface TeardownScriptOptions {
  /** The install root; `DEFAULT_INSTALL_ROOT` unless a test names another. Vetted by `assertValidRoot`. */
  readonly root?: string;
  /** The arashouse version that generated the script. */
  readonly version: string;
  /** The SHA-256 of `host\setup-host.ps1` and `sql\setup-sql.ps1` as written next to it: a changed one is not run. */
  readonly setupHostSha256: string;
  readonly setupSqlSha256: string;
  /** Where its own SQL reads go: the host's default instance unless a test names a LocalDB instance of its own. */
  readonly dataSource?: string;
}

const SHA256 = /^[0-9a-f]{64}$/;
const VERSION = /^[0-9A-Za-z.+-]{1,64}$/;
const DATA_SOURCE = /^(lpc:\.|\(localdb\)\\[A-Za-z0-9_]{1,64})$/;

/** A regex source for `name` (derived for slot 77) with its slot number replaced by any two digits. */
function anySlot(name: string): string {
  const escaped = name.replace(/[.*+?^${}()|[\]\\-]/g, "\\$&");
  if (escaped.split("77").length !== 2) throw new Error(`"${name}" does not hold the slot number 77 exactly once`);
  return escaped.replace("77", "[0-9]{2}");
}

const escape = (name: string): string => name.replace(/[.*+?^${}()|[\]\\-]/g, "\\$&");

/** `^(?:a|b|c)$` */
const exactly = (sources: readonly string[]): string => `^(?:${sources.join("|")})$`;

/**
 * The names the script reports as the tool's, as case-insensitive regexes, each derived from names.ts for every
 * registered flavor: a slot's (`ah-<key>-<NN>`, ...) and a baseline build's (`ah-build-<key>`, ...). Nothing
 * else of a kind is reported, so the `ah-pp-*` and `arashouse_pp_*` objects on the host, which are not the
 * pool's, stay out of it.
 */
export function teardownPatterns(flavors: readonly FlavorKey[] = FLAVOR_KEYS) {
  const at77 = (flavor: FlavorKey) => ({ flavor, slot: 77 });
  /** Per flavor: a slot's name with any two digits for its number, then `tail` (a regex source) as it is. */
  const slot = (f: (flavor: FlavorKey) => string, tail = "") => exactly(flavors.map((k) => anySlot(f(k)) + tail));
  const build = (f: (flavor: FlavorKey) => string, tail = "") => exactly(flavors.map((k) => escape(f(k)) + tail));
  return {
    slotAlias: slot((k) => webAlias(at77(k))),
    slotPool: slot((k) => `${webAlias(at77(k))}-`, "[a-z]+"),
    slotService: slot((k) => agentServiceName(at77(k))),
    slotDatabase: slot((k) => databaseName(at77(k))),
    slotLogin: slot((k) => `${databaseName(at77(k))}_`, "(?:dbo|reg)"),
    buildAlias: build((k) => buildNames(k).alias),
    buildPool: build((k) => buildScratch(k).poolPrefix, "[a-z]+"),
    buildDatabase: build((k) => buildNames(k).database),
    buildLogin: build((k) => `${buildNames(k).database}_`, "(?:dbo|reg)"),
    buildFolder: build((k) => k, `(?:\\.(?:${BUILD_SCRATCH_SUFFIXES.join("|")}))?`),
  };
}

function psList(items: readonly string[]): string {
  return `@(${items.map(psQuote).join(", ")})`;
}

/**
 * The text of `teardown.ps1`. Every path in it is derived from `root` by names.ts; it changes nothing without
 * `-Apply`, removes only the goldens by their derived paths and what its two child scripts remove, and runs
 * those only when they are the bytes it was generated with. Throws when an option is unusable.
 */
export function renderTeardownScript(options: TeardownScriptOptions): string {
  if (!VERSION.test(options.version)) throw new Error("the version must be 1 to 64 letters, digits, '.', '+' or '-'");
  if (!SHA256.test(options.setupHostSha256) || !SHA256.test(options.setupSqlSha256)) throw new Error("the SHA-256 of a child script is not 64 hex digits");
  const root = assertValidRoot(options.root ?? DEFAULT_INSTALL_ROOT);
  if (root.includes("'")) throw new Error("the install root must not hold a quote");
  const dataSource = options.dataSource ?? SQL_DATA_SOURCE;
  if (!DATA_SOURCE.test(dataSource)) throw new Error(`the data source must be ${SQL_DATA_SOURCE} or a LocalDB instance, got "${dataSource}"`);
  const p = teardownPatterns();
  const goldens = FLAVOR_KEYS.map((key) => `    ${psQuote(key)} = ${psQuote(goldenDir(key, root))}`).join("\n");

  return `# teardown.ps1: removes the arashouse pool from this host (ticket 49), generated by \`arashouse teardown\` ${options.version}.
# Run it in an elevated Windows PowerShell 5.1, after \`arashouse teardown --yes\` has destroyed every slot from WSL. Without -Apply it
# prints what it would change (\`would do:\` lines, and the dry runs of its two child scripts) and changes nothing; with -Apply each change
# is printed (\`do:\`) and made. The last thing it prints is \`result:\` and the result as JSON (also written next to it with -Apply).
#
#   teardown.ps1 [-Apply]                        drop the SQL objects (setup-sql.ps1 -Uninstall), then remove the broker service
#   teardown.ps1 -Goldens [-Apply]               ... and first remove golden\\<flavor> for every flavor
#   teardown.ps1 -KeepSql [-Apply]               ... but leave the SQL objects
#   teardown.ps1 -Goldens -RemoveRoot [-Apply]   ... and last remove ${root} itself, if it holds only arashouse folders
#
# Refused, with nothing changed, while any slot of the pool is left (its folders, IIS application or pools, agent service, database
# or logins), or (with -Goldens or -RemoveRoot) while a baseline build has left its throw-away instance. It removes only names that
# match the allowlist, derived for the registered flavors (${FLAVOR_KEYS.join(", ")}); the captain's installers in the repo's media\\
# folder are not on this host's install root and are never touched. Before and after, it fingerprints the deny-list and prints the
# objects' names (never their settings) with whether each is unchanged. It reads no secret and writes none.
# Exit codes: 0 ok, 1 a step failed or something is left, 2 refused arguments, 3 a child script is not the one it was generated
# with, 4 not elevated.
param(
    [switch]$Apply,
    [switch]$Goldens,
    [switch]$KeepSql,
    [switch]$RemoveRoot
)
$ErrorActionPreference = 'Stop'

# ---- generated from src/core (names.ts, guards.ts, flavors.ts, setup-sql.ts); do not edit ----
$ToolVersion = ${psQuote(options.version)}
$Root = ${psQuote(root)}
$RootFolders = ${psList(ROOT_FOLDERS)}
$SlotsDir = ${psQuote(`${root}\\slots`)}
$VaultsDir = ${psQuote(`${root}\\vaults`)}
$GoldenBuildDir = ${psQuote(`${root}\\golden-build`)}
$GoldenDirs = [ordered]@{
${goldens}
}
$FlavorKeys = ${psList(FLAVOR_KEYS)}
$SlotAlias = ${psQuote(p.slotAlias)}
$SlotPool = ${psQuote(p.slotPool)}
$SlotService = ${psQuote(p.slotService)}
$SlotDatabase = ${psQuote(p.slotDatabase)}
$SlotLogin = ${psQuote(p.slotLogin)}
$BuildAlias = ${psQuote(p.buildAlias)}
$BuildPool = ${psQuote(p.buildPool)}
$BuildDatabase = ${psQuote(p.buildDatabase)}
$BuildLogin = ${psQuote(p.buildLogin)}
$BuildFolder = ${psQuote(p.buildFolder)}
$AdminDatabase = ${psQuote(UTILITY_DATABASE)}
$PoolLogin = ${psQuote(POOL_LOGIN)}
$SignerNames = @(${SIGNERS.map((s) => psQuote(s.name)).join(", ")})
$BrokerService = ${psQuote(BROKER_SERVICE_NAME)}
$FirewallRule = ${psQuote(HOST_TUNING_FIREWALL_RULE)}
$TuningStateFile = Join-Path $env:LOCALAPPDATA ${psQuote(HOST_TUNING_STATE)}
$DeniedRoots = ${psList(DENIED_INSTALL_ROOTS)}
$DeniedServicePrefixes = ${psList(DENIED_SERVICE_PREFIXES)}
$HostScript = Join-Path $PSScriptRoot ${psQuote(TEARDOWN_CHILDREN.host)}
$HostScriptSha256 = ${psQuote(options.setupHostSha256)}
$SqlScript = Join-Path $PSScriptRoot ${psQuote(TEARDOWN_CHILDREN.sql)}
$SqlScriptSha256 = ${psQuote(options.setupSqlSha256)}
$ResultFile = Join-Path $PSScriptRoot ${psQuote(TEARDOWN_RESULT_FILE)}
$ConnectionString = 'Data Source=${dataSource};Initial Catalog=master;Integrated Security=SSPI;Connect Timeout=10;Pooling=False;Application Name=arashouse-teardown'
# ---- end of generated values ----

$Changes = New-Object System.Collections.ArrayList
$Planned = New-Object System.Collections.ArrayList
$Errors = New-Object System.Collections.ArrayList
$Notes = New-Object System.Collections.ArrayList

function Fail([int]$Code, [string]$Message) {
    [Console]::Error.WriteLine("error: $Message")
    exit $Code
}

# ps-common.ts's functions stop through this; here a stop is an error the caller handles, not the end of the script.
function Stop-Step([string]$Message) { throw $Message }

# Every change of this script's own goes through here: without -Apply it is only printed.
function Invoke-Change([string]$Text, [scriptblock]$Action) {
    if (-not $Apply) {
        Write-Host "would do: $Text"
        [void]$Planned.Add($Text)
        return
    }
    Write-Host "do: $Text"
    & $Action
    [void]$Changes.Add($Text)
}

function Test-Elevated {
    $principal = New-Object Security.Principal.WindowsPrincipal([Security.Principal.WindowsIdentity]::GetCurrent())
    return $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
}

function Get-Sha256([string]$Path) {
    if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) { return $null }
    return (Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToLowerInvariant()
}

function Test-ReparsePoint([string]$Path) {
    $item = Get-Item -LiteralPath $Path -Force -ErrorAction SilentlyContinue
    return ($null -ne $item) -and (($item.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0)
}

${PS_PATHS_AND_PRINTS}

${PS_IIS}

${PS_DENY_LIST_PRINTS}

# ---- reads ----

function Get-SqlNames {
    # The tool's databases and logins, by the allowlist: sys.databases and sys.server_principals are read only with LIKE 'arashouse[_]%'
    # (and the broker's exact name; the certificates' logins are arashouse_admin_*), so no other database or login is listed; then only derived names are kept.
    $c = New-Object Data.SqlClient.SqlConnection $ConnectionString
    $c.Open()
    try {
        $read = {
            param([string]$Text)
            $cmd = $c.CreateCommand()
            $cmd.CommandText = $Text
            [void]$cmd.Parameters.AddWithValue('@pool', $PoolLogin)
            $r = $cmd.ExecuteReader()
            $out = New-Object System.Collections.ArrayList
            try { while ($r.Read()) { [void]$out.Add([string]$r.GetValue(0)) } } finally { $r.Close() }
            return , @($out)
        }
        $dbs = & $read "SELECT name FROM sys.databases WHERE name LIKE N'arashouse[_]%'"
        $logins = & $read "SELECT name FROM sys.server_principals WHERE name LIKE N'arashouse[_]%' OR name = @pool"
    } finally { $c.Dispose() }
    return [ordered]@{
        slotDatabases = @($dbs | Where-Object { $_ -match $SlotDatabase } | Sort-Object)
        slotLogins = @($logins | Where-Object { $_ -match $SlotLogin } | Sort-Object)
        buildDatabases = @($dbs | Where-Object { $_ -match $BuildDatabase } | Sort-Object)
        buildLogins = @($logins | Where-Object { $_ -match $BuildLogin } | Sort-Object)
        setupSql = @(@($dbs | Where-Object { $_ -ieq $AdminDatabase }) + @($logins | Where-Object { $_ -ieq $PoolLogin -or $SignerNames -contains $_ }) | Sort-Object)
    }
}

function Get-IisNames {
    $mgr = Get-Iis
    try {
        $apps = New-Object System.Collections.ArrayList
        foreach ($s in $mgr.Sites) {
            foreach ($app in $s.Applications) {
                $first = $app.Path.TrimStart('/').Split('/')[0]
                if ($first -match $SlotAlias -or $first -match $BuildAlias) { [void]$apps.Add(('{0}{1}' -f $s.Name, $app.Path)) }
            }
        }
        $pools = @($mgr.ApplicationPools | ForEach-Object { $_.Name } | Where-Object { $_ -match $SlotPool -or $_ -match $BuildPool })
    } finally { $mgr.Dispose() }
    return [ordered]@{
        slotApplications = @($apps | Where-Object { ($_ -split '/')[1] -match $SlotAlias } | Sort-Object)
        slotPools = @($pools | Where-Object { $_ -match $SlotPool } | Sort-Object)
        buildApplications = @($apps | Where-Object { ($_ -split '/')[1] -match $BuildAlias } | Sort-Object)
        buildPools = @($pools | Where-Object { $_ -match $BuildPool } | Sort-Object)
    }
}

function Test-Listable([string]$Dir) {
    try { Get-ChildItem -LiteralPath $Dir -Force -ErrorAction Stop | Out-Null; return $true } catch { return $false }
}

function Get-ChildNames([string]$Dir, [int]$Depth) {
    # The entries under $Dir, $Depth levels down, relative to the root (slots\\12sp9\\01), one per line of output; none when $Dir is absent.
    if (-not (Test-Path -LiteralPath $Dir -PathType Container)) { return }
    $items = @(Get-ChildItem -LiteralPath $Dir -Force)
    for ($i = 1; $i -lt $Depth; $i++) { $items = @($items | Where-Object { $_.PSIsContainer } | ForEach-Object { Get-ChildItem -LiteralPath $_.FullName -Force }) }
    $items | ForEach-Object { $_.FullName.Substring($Root.Length + 1) } | Sort-Object
}

function Get-DefenderExcluded {
    try {
        $paths = @((Get-MpPreference -ErrorAction Stop).ExclusionPath)
        if ($paths -match '^N/A') { return $null }
        return [bool]($paths | Where-Object { $_ -ieq $Root })
    } catch { return $null }
}

function Get-TuningRecord {
    # The items ticket 44's host-tuning.ps1 applied and recorded, by name (Wsl, Sql, Defender, Firewall); none when unreadable.
    try { $record = Get-Content -LiteralPath $TuningStateFile -Raw -ErrorAction Stop | ConvertFrom-Json } catch { return }
    foreach ($item in @('Wsl', 'Sql', 'Defender', 'Firewall')) { if ($record.PSObject.Properties[$item.ToLower()]) { $item } }
}

function Get-Leftovers {
    # What of the tool is on the host, by name: each kind read on its own, so one that cannot be read (IIS without elevation, SQL
    # Server unreachable) is reported as unread rather than as empty. (Assigned with if/else, not $(if ...): a subexpression turns
    # an empty array into $null and a one-item array into the item.)
    $left = [ordered]@{ unread = @() }
    # The tool's folders are closed to the worker (golden\\, vaults\\, golden-build\\): one that cannot be listed is unread, not empty.
    $hidden = @($SlotsDir, $VaultsDir, ($Root + '\\golden'), $GoldenBuildDir | Where-Object { (Test-Path -LiteralPath $_) -and -not (Test-Listable $_) })
    foreach ($h in $hidden) { $left.unread += "folders: $h cannot be listed here" }
    try { $left.slotFolders = @(@(Get-ChildNames $SlotsDir 2) + @(Get-ChildNames $VaultsDir 1)) } catch { $left.slotFolders = @() }
    try { $iis = Get-IisNames } catch { $iis = $null; $left.unread += "IIS: $($_.Exception.Message)" }
    try { $sql = Get-SqlNames } catch { $sql = $null; $left.unread += "SQL Server: $($_.Exception.Message)" }
    $services = @(Get-CimInstance Win32_Service | ForEach-Object { $_.Name })
    if ($iis) { $left.slotIis = @(@($iis.slotApplications) + @($iis.slotPools)) } else { $left.slotIis = @() }
    $left.slotServices = @($services | Where-Object { $_ -match $SlotService } | Sort-Object)
    if ($sql) { $left.slotSql = @(@($sql.slotDatabases) + @($sql.slotLogins)) } else { $left.slotSql = @() }
    try { $left.goldens = @($GoldenDirs.Keys | Where-Object { Test-Path -LiteralPath $GoldenDirs[$_] } | ForEach-Object { 'golden\\' + $_ }) } catch { $left.goldens = @() }
    try { $building = @(Get-ChildNames $GoldenBuildDir 1) } catch { $building = @() }
    $left.buildFolders = @($building | Where-Object { ($_ -split '\\\\')[-1] -match $BuildFolder })
    if ($iis) { $left.buildIis = @(@($iis.buildApplications) + @($iis.buildPools)) } else { $left.buildIis = @() }
    if ($sql) { $left.buildSql = @(@($sql.buildDatabases) + @($sql.buildLogins)); $left.setupSql = @($sql.setupSql) } else { $left.buildSql = @(); $left.setupSql = @() }
    $left.broker = @($services | Where-Object { $_ -ieq $BrokerService })
    $left.firewall = @(Get-NetFirewallRule -Name $FirewallRule -ErrorAction SilentlyContinue | ForEach-Object { $_.Name })
    $defender = Get-DefenderExcluded
    if ($defender -eq $true) { $left.defender = @("exclusion $Root") } else { $left.defender = @() }
    $left.defenderRead = ($null -ne $defender)
    if (Test-Path -LiteralPath $Root) { $left.root = @($Root) } else { $left.root = @() }
    return $left
}

function Get-Slots($Left) { return , @(@($Left.slotFolders) + @($Left.slotIis) + @($Left.slotServices) + @($Left.slotSql)) }

function Get-Builds($Left) { return , @(@($Left.buildFolders) + @($Left.buildIis) + @($Left.buildSql)) }

function Add-Note([string]$Text) { if (-not $Notes.Contains($Text)) { [void]$Notes.Add($Text) } }

function Get-DenyList {
    try { return Get-DenyListPrints } catch { Add-Note "the deny-list cannot be fingerprinted here: $($_.Exception.Message)"; return $null }
}

# ---- changes ----

function Remove-Golden([string]$Path) {
    if (-not (Test-Under $Path ($Root + '\\golden'))) { throw "refused: $Path is not under $Root\\golden" }
    if ($Path -match '(?i)program files') { throw "refused: $Path is under Program Files" }
    $links = @(Get-ChildItem -LiteralPath $Path -Recurse -Force -Attributes ReparsePoint -ErrorAction SilentlyContinue)
    if ((Test-ReparsePoint $Path) -or $links.Count -gt 0) { throw "refused to remove $($Path): it is or holds a junction or link" }
    Remove-Item -LiteralPath $Path -Recurse -Force
}

function Invoke-Child([string]$Name, [string]$Script, [string[]]$Arguments) {
    # A child script in its own Windows PowerShell; its lines are printed under its name, its result is parsed back.
    $all = @('-NoProfile', '-NonInteractive', '-ExecutionPolicy', 'Bypass', '-File', $Script) + $Arguments
    if ($Apply) { $all += '-Apply' }
    Write-Host ('run: {0} {1}' -f (Split-Path -Leaf $Script), ((@($Arguments) + @($(if ($Apply) { '-Apply' }))) -join ' ').Trim())
    $ErrorActionPreference = 'Continue'
    $lines = @(& (Join-Path $PSHOME 'powershell.exe') @all 2>&1 | ForEach-Object { [string]$_ })
    $code = $LASTEXITCODE
    $ErrorActionPreference = 'Stop'
    $at = [array]::IndexOf($lines, 'result:')
    $head = $(if ($at -ge 0) { $lines[0..([Math]::Max(0, $at - 1))] } else { $lines })
    if ($at -eq 0) { $head = @() }
    foreach ($l in $head) { if ($l.Trim()) { Write-Host "  $($Name): $l" } }
    $result = $null
    if ($at -ge 0) { try { $result = ($lines[($at + 1)..($lines.Count - 1)] -join [Environment]::NewLine) | ConvertFrom-Json } catch { } }
    if ($result) {
        foreach ($c in @($result.changes)) { if ($c) { [void]$Changes.Add("$($Name): $c") } }
        foreach ($c in @($result.planned)) { if ($c) { [void]$Planned.Add("$($Name): $c") } }
    }
    # A dry run is never done, so a child's own ok counts only once it has applied.
    return [ordered]@{ exitCode = $code; ok = ($code -eq 0) -and $result -and ($result.ok -or -not $Apply); errors = $(if ($result) { @($result.errors) } else { @('no result was printed') }) }
}

# ---- main ----

if ($RemoveRoot -and -not $Goldens) { Fail 2 '-RemoveRoot removes golden\\ too: give -Goldens with it' }
if ($RemoveRoot -and $KeepSql) { Fail 2 '-RemoveRoot removes sqldata\\, which holds arashouse_admin''s files: it cannot go with -KeepSql' }
if ($Apply -and -not (Test-Elevated)) { Fail 4 '-Apply needs an elevated PowerShell (Run as administrator)' }
foreach ($child in @(@($HostScript, $HostScriptSha256), @($SqlScript, $SqlScriptSha256))) {
    if ((Get-Sha256 $child[0]) -ne $child[1]) { Fail 3 ('{0} is missing or not the script this one was generated with; write the bundle again with arashouse teardown' -f $child[0]) }
}
if (Test-ReparsePoint $Root) { Fail 2 "refused: $Root is a junction or symbolic link" }
if (-not $Apply) { Write-Host 'dry run: nothing is changed; add -Apply (elevated) to make these changes' }

$denyBefore = Get-DenyList
if ($Apply -and -not $denyBefore) { Fail 1 ('the deny-list could not be fingerprinted, so nothing was changed: {0}' -f ($Notes -join '; ')) }
if ($denyBefore) {
    Write-Host ('deny-list before: {0} objects' -f $denyBefore.Count)
    foreach ($name in $denyBefore.Keys) { Write-Host "  $name" }
}

$before = Get-Leftovers
foreach ($u in $before.unread) { Add-Note "not read: $u" }
$slotsLeft = Get-Slots $before
$buildsLeft = Get-Builds $before
$steps = [ordered]@{ goldens = 'skipped'; sql = 'skipped'; host = 'not run' }
$sql = $null
$hostRun = $null
try {
    if ($Apply -and $before.unread.Count -gt 0) { throw ('refused: {0}' -f ($before.unread -join '; ')) }
    if ($slotsLeft.Count -gt 0) { throw ('refused: slots of the pool are left ({0}); run arashouse teardown --yes from WSL first' -f ($slotsLeft -join ', ')) }
    if (($Goldens -or $RemoveRoot) -and $buildsLeft.Count -gt 0) { throw ('refused: a baseline build left its throw-away instance ({0}); remove it with baseline-build.ps1 -Cleanup first' -f ($buildsLeft -join ', ')) }

    if ($Goldens) {
        foreach ($key in $GoldenDirs.Keys) {
            $path = $GoldenDirs[$key]
            if (Test-Path -LiteralPath $path) { Invoke-Change "remove the $key golden, $path" { Remove-Golden $path } }
        }
        $steps.goldens = 'ok'
    }
    if (-not $KeepSql) {
        $sql = Invoke-Child 'sql' $SqlScript @('-Uninstall')
        $steps.sql = $(if ($sql.ok) { 'ok' } else { 'failed' })
        if (-not $sql.ok) { throw ('setup-sql.ps1 -Uninstall did not finish (exit {0}): {1}; the broker is left installed' -f $sql.exitCode, ($sql.errors -join '; ')) }
    }
    $hostArgs = @('-Uninstall') + @($(if ($RemoveRoot) { '-RemoveRoot' }))
    $hostRun = Invoke-Child 'host' $HostScript $hostArgs
    $steps.host = $(if ($hostRun.ok) { 'ok' } else { 'failed' })
    if (-not $hostRun.ok) { throw ('setup-host.ps1 -Uninstall did not finish (exit {0}): {1}' -f $hostRun.exitCode, ($hostRun.errors -join '; ')) }
} catch {
    [void]$Errors.Add($_.Exception.Message)
    [Console]::Error.WriteLine("error: $($_.Exception.Message)")
}

$after = Get-Leftovers
$denyAfter = Get-DenyList
$deny = New-Object System.Collections.ArrayList
if ($denyBefore -and $denyAfter) {
    Write-Host ('deny-list after: {0} objects' -f $denyAfter.Count)
    foreach ($name in $denyBefore.Keys) {
        $now = $(if (-not $denyAfter.Contains($name)) { 'gone' } elseif ($denyAfter[$name] -eq $denyBefore[$name]) { 'unchanged' } else { 'changed' })
        Write-Host "  $($name): $now"
        [void]$deny.Add([ordered]@{ name = $name; after = $now })
    }
    foreach ($name in $denyAfter.Keys) {
        if ($denyBefore.Contains($name)) { continue }
        Write-Host "  $($name): new"
        [void]$deny.Add([ordered]@{ name = $name; after = 'new' })
    }
    $moved = @($deny | Where-Object { $_.after -ne 'unchanged' } | ForEach-Object { $_.name })
    if ($moved.Count -gt 0) { [void]$Errors.Add(('the deny-list changed: {0}' -f ($moved -join ', '))) }
}

# What must be gone once it has applied: everything of the slots, the broker, the firewall rule and the Defender exclusion; the
# goldens and the build's leftovers with -Goldens; the SQL objects unless -KeepSql; the root with -RemoveRoot.
$mustGo = @('slotFolders', 'slotIis', 'slotServices', 'slotSql', 'broker', 'firewall', 'defender')
if ($Goldens) { $mustGo += @('goldens', 'buildFolders', 'buildIis', 'buildSql') }
if (-not $KeepSql) { $mustGo += 'setupSql' }
if ($RemoveRoot) { $mustGo += 'root' }
$left = @($mustGo | ForEach-Object { @($after[$_]) } | Where-Object { $_ })
foreach ($name in $left) { Write-Host "left: $name" }
if ($after.firewall.Count -gt 0) { Add-Note ("the firewall rule $FirewallRule is ticket 44's: remove it with host-tuning.ps1 -Undo Firewall -Apply") }
# Host settings an earlier arashouse applied (ticket 44) are recorded by host-tuning.ps1 for this Windows user; it undoes them.
$tuned = @(Get-TuningRecord)
if ($tuned.Count -gt 0) { Add-Note ('host-tuning.ps1 recorded host settings an earlier arashouse applied ({0}): undo them with host-tuning.ps1 -Undo {0} -Apply' -f ($tuned -join ',')) }
if (-not $after.defenderRead) { Add-Note 'the Defender exclusions cannot be read here, so an exclusion of the root would not be seen' }
foreach ($n in $Notes) { Write-Host "note: $n" }
$ok = ($Errors.Count -eq 0) -and $(if ($Apply) { $left.Count -eq 0 -and $after.unread.Count -eq 0 -and $null -ne $denyAfter } else { $true })

$record = [ordered]@{
    schema = 1
    tool = 'teardown.ps1'
    version = $ToolVersion
    time = (Get-Date).ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ssZ')
    applied = [bool]$Apply
    elevated = [bool](Test-Elevated)
    ok = [bool]$ok
    options = [ordered]@{ goldens = [bool]$Goldens; keepSql = [bool]$KeepSql; removeRoot = [bool]$RemoveRoot }
    steps = $steps
    before = $before
    after = $after
    left = @($left)
    denyList = [ordered]@{ before = $(if ($denyBefore) { @($denyBefore.Keys) } else { $null }); after = @($deny) }
    changes = @($Changes)
    planned = @($Planned)
    notes = @($Notes)
    errors = @($Errors)
}
$json = $record | ConvertTo-Json -Depth 6
if ($Apply) { [IO.File]::WriteAllText($ResultFile, $json, (New-Object Text.ASCIIEncoding)) }
Write-Host 'result:'
Write-Host $json
if (-not $ok) { exit 1 }
exit 0
`;
}
